Definition enq_is_app (st : astate) : bool :=
  match rev (a_qloc st) with b :: _ => negb (b_count b =? Q_BATCH) | [] => false end.

Lemma enq_is_app_spec : forall st1 ch,
  (enq_is_app st1 = true <-> exists s, enq_app st1 ch = Some s).
Proof.
